#!/usr/bin/env sh
# opc — OneProxyClick control helper for KaliTerm / Termux / proot Ubuntu (POSIX sh: dash, ash, bash).
#
# Talks to the app's local control API (127.0.0.1 only) with curl, or python3 when curl is missing.
#
# Install:
#   cp __OPC_EXPORT_DIR__/opc-cli.sh ~/opc && chmod +x ~/opc
#   (or: alias opc='sh __OPC_EXPORT_DIR__/opc-cli.sh')
#
# Generated by OneProxyClick (Ajustes/Settings > KaliTerm Bridge). The token authorises the API;
# regenerate it in the app if this file leaks (the script is re-exported automatically).

OPC_TOKEN="${OPC_TOKEN:-__OPC_TOKEN__}"
OPC_API="${OPC_API:-http://127.0.0.1:__OPC_API_PORT__}"
OPC_DIR="${OPC_DIR:-__OPC_EXPORT_DIR__}"
OPC_STREAM="${OPC_STREAM:-$OPC_DIR/live_stream.jsonl}"
# OPC_HTTP=curl|python forces the HTTP client (default: curl if available).
OPC_HTTP="${OPC_HTTP:-}"

TAB=$(printf '\t')
if [ -t 1 ] && [ -z "${NO_COLOR:-}" ]; then
  ESC=$(printf '\033')
  C_RST="${ESC}[0m"; C_DIM="${ESC}[2m"; C_BLD="${ESC}[1m"; C_RED="${ESC}[31m"; C_GRN="${ESC}[32m"
  C_YEL="${ESC}[33m"; C_BLU="${ESC}[34m"; C_MAG="${ESC}[35m"; C_CYN="${ESC}[36m"
else
  C_RST=; C_DIM=; C_BLD=; C_RED=; C_GRN=; C_YEL=; C_BLU=; C_MAG=; C_CYN=
fi

_die() { printf 'opc: %s\n' "$*" >&2; exit 1; }
_have() { command -v "$1" >/dev/null 2>&1; }

# Escape a value for use inside a JSON string literal.
_json_str() { printf '%s' "$1" | sed -e 's/\\/\\\\/g' -e 's/"/\\"/g' -e "s/$TAB/\\\\t/g"; }

# _http METHOD PATH [JSON_BODY] -> prints the response body, then the HTTP status on the last line
# (000 = could not connect).
_http() {
  _m="$1"; _p="$2"; _b="${3:-}"
  [ "$_m" = POST ] && [ -z "$_b" ] && _b='{}'
  _client="$OPC_HTTP"
  if [ -z "$_client" ]; then
    if _have curl; then _client=curl; elif _have python3; then _client=python; else _die "needs curl or python3"; fi
  fi
  if [ "$_client" = curl ]; then
    # --noproxy: never send control calls through an http_proxy (it may be OneProxyClick itself)
    if [ "$_m" = POST ]; then
      curl -sS --noproxy '*' -m 20 -X POST -H "Authorization: Bearer $OPC_TOKEN" \
        -H 'Content-Type: application/json' --data "$_b" -w '\n%{http_code}\n' "$OPC_API$_p" 2>/dev/null
    else
      curl -sS --noproxy '*' -m 20 -H "Authorization: Bearer $OPC_TOKEN" \
        -w '\n%{http_code}\n' "$OPC_API$_p" 2>/dev/null
    fi
  else
    python3 - "$_m" "$OPC_API$_p" "$OPC_TOKEN" "$_b" <<'PY'
import sys, json, urllib.request, urllib.error
method, url, token, body = sys.argv[1:5]
data = body.encode("utf-8") if method == "POST" else None
req = urllib.request.Request(url, data=data, method=method)
req.add_header("Authorization", "Bearer " + token)
req.add_header("Content-Type", "application/json")
opener = urllib.request.build_opener(urllib.request.ProxyHandler({}))  # ignore http_proxy
try:
    with opener.open(req, timeout=20) as r:
        out, code = r.read().decode("utf-8", "replace"), r.status
except urllib.error.HTTPError as e:
    out, code = e.read().decode("utf-8", "replace"), e.code
except Exception as e:
    out, code = json.dumps({"ok": False, "message": str(e)}), 0
sys.stdout.write(out.rstrip("\n") + "\n" + "%03d" % code + "\n")
PY
  fi
}

# Extract a top-level string field from a JSON object (jq > python3 > sed).
_field() {
  if _have jq; then
    printf '%s' "$1" | jq -r --arg k "$2" '.[$k] // empty' 2>/dev/null
  elif _have python3; then
    printf '%s' "$1" | python3 -c 'import sys,json
try: v=json.load(sys.stdin).get(sys.argv[1])
except Exception: v=None
print("" if v is None else v)' "$2" 2>/dev/null
  else
    printf '%s' "$1" | sed -n "s/.*\"$2\":\"\\([^\"]*\\)\".*/\\1/p"
  fi
}

# Pretty status block from a response containing {"status":{...}}.
_print_status() {
  if _have jq; then
    printf '%s' "$1" | jq '.status' 2>/dev/null
  elif _have python3; then
    printf '%s' "$1" | python3 -c 'import sys,json
try: print(json.dumps(json.load(sys.stdin).get("status"), indent=2))
except Exception: pass' 2>/dev/null
  else
    printf '%s\n' "$1"
  fi
}

# _call METHOD PATH [BODY] [show_status]
_call() {
  _resp=$(_http "$1" "$2" "${3:-}")
  _code=$(printf '%s\n' "$_resp" | tail -n 1)
  _body=$(printf '%s\n' "$_resp" | sed '$d')
  case "$_code" in
    2??)
      _msg=$(_field "$_body" message)
      [ -n "$_msg" ] && printf '%s✔%s %s\n' "$C_GRN" "$C_RST" "$_msg"
      [ "${4:-}" = status ] && _print_status "$_body"
      return 0 ;;
    000|"")
      printf '%s✘%s cannot reach %s — is OneProxyClick running? (open the app once; check the API port in Settings)\n' \
        "$C_RED" "$C_RST" "$OPC_API" >&2
      return 2 ;;
    *)
      _msg=$(_field "$_body" message)
      printf '%s✘%s [%s] %s\n' "$C_RED" "$C_RST" "$_code" "${_msg:-$_body}" >&2
      return 1 ;;
  esac
}

_color_method() {
  case "$1" in
    GET) printf '%s' "$C_BLU" ;; POST) printf '%s' "$C_GRN" ;;
    PUT|PATCH) printf '%s' "$C_YEL" ;; DELETE) printf '%s' "$C_RED" ;;
    *) printf '%s' "$C_MAG" ;;
  esac
}

_color_status() {
  case "$1" in
    2*) printf '%s' "$C_GRN" ;; 3*) printf '%s' "$C_CYN" ;;
    4*) printf '%s' "$C_YEL" ;; *) printf '%s' "$C_RED" ;;
  esac
}

# JSON lines on stdin -> "METHOD<TAB>STATUS<TAB>host<TAB>path<TAB>ms"
_extract() {
  if _have jq; then
    jq -r --unbuffered '[.method, ((.response.status_code // "ERR")|tostring), .host, (.path + (if (.query // "") != "" then "?" + .query else "" end)), ((.duration_ms // 0)|tostring)] | @tsv' 2>/dev/null
  elif _have python3; then
    python3 -u -c '
import sys, json
for line in sys.stdin:
    try:
        o = json.loads(line)
    except Exception:
        continue
    r = o.get("response") or {}
    q = o.get("query") or ""
    path = (o.get("path") or "") + ("?" + q if q else "")
    print("\t".join([o.get("method", ""), str(r.get("status_code", "ERR")), o.get("host", ""), path, str(o.get("duration_ms", 0))]), flush=True)
'
  else
    sed -n "s/.*\"method\":\"\\([^\"]*\\)\".*\"host\":\"\\([^\"]*\\)\".*\"path\":\"\\([^\"]*\\)\".*/\\1${TAB}?${TAB}\\2${TAB}\\3${TAB}0/p"
  fi
}

_print_row() { # method status host path ms [time]
  printf '%s %s%s%-7s%s %s%-3s%s %s%s%s%s %s%sms%s\n' \
    "${C_DIM}${6:-}${C_RST}" "$(_color_method "$1")" "$C_BLD" "$1" "$C_RST" \
    "$(_color_status "$2")" "$2" "$C_RST" "$C_BLD" "$3" "$C_RST" "$4" "$C_DIM" "$5" "$C_RST"
}

cmd_watch() {
  [ -f "$OPC_STREAM" ] || printf '%swaiting for %s (enable Auto-JSON GET/POST in the app)…%s\n' "$C_DIM" "$OPC_STREAM" "$C_RST"
  printf '%stail -F %s  (Ctrl+C to stop)%s\n' "$C_DIM" "$OPC_STREAM" "$C_RST"
  tail -n "${1:-0}" -F "$OPC_STREAM" 2>/dev/null | _extract | while IFS="$TAB" read -r m s h p ms; do
    _print_row "$m" "$s" "$h" "$p" "$ms" "$(date +%H:%M:%S)"
  done
}

cmd_fmt() {
  _extract | while IFS="$TAB" read -r m s h p ms; do _print_row "$m" "$s" "$h" "$p" "$ms"; done
}

# Receiver for "Forward to local port": HTTP (default) or raw TCP JSON lines; prints one JSON per line.
cmd_listen() {
  _have python3 || _die "listen needs python3 (or: nc -lk ${1:-9090})"
  printf '%slistening on 127.0.0.1:%s (%s) — pipe into: opc fmt%s\n' "$C_DIM" "${1:-9090}" "${2:-http}" "$C_RST" >&2
  python3 -u - "${1:-9090}" "${2:-http}" <<'PY'
import sys, socketserver, http.server
port, mode = int(sys.argv[1]), sys.argv[2]
class H(http.server.BaseHTTPRequestHandler):
    def do_POST(self):
        n = int(self.headers.get("Content-Length") or 0)
        print(self.rfile.read(n).decode("utf-8", "replace").strip(), flush=True)
        self.send_response(204); self.end_headers()
    def log_message(self, *a): pass
class T(socketserver.StreamRequestHandler):
    def handle(self):
        for line in self.rfile:
            print(line.decode("utf-8", "replace").rstrip("\n"), flush=True)
socketserver.ThreadingTCPServer.allow_reuse_address = True
http.server.ThreadingHTTPServer.allow_reuse_address = True
srv = http.server.ThreadingHTTPServer(("127.0.0.1", port), H) if mode == "http" \
    else socketserver.ThreadingTCPServer(("127.0.0.1", port), T)
try:
    srv.serve_forever()
except KeyboardInterrupt:
    pass
PY
}

cmd_help() {
  cat <<EOF
${C_BLD}opc${C_RST} — OneProxyClick control  (API: $OPC_API)

  opc on [port]                 start VPN + proxy (optional proxy port)
  opc off                       stop VPN + proxy (releases held requests)
  opc status                    tunnel / proxy port / intercept / host filter
  opc intercept on|off|toggle   Intercept mode
  opc filter "<regex>"          intercept only matching hosts ("" = all)
  opc watch [N]                 live table from live_stream.jsonl (last N lines first)
  opc fmt                       format JSON lines from stdin (e.g. opc listen | opc fmt)
  opc listen [port] [http|tcp]  receiver for "Forward to local port"
  opc last                      print last_sent.json

Env: OPC_TOKEN, OPC_API, OPC_DIR, OPC_STREAM, OPC_HTTP=curl|python, NO_COLOR=1
EOF
}

main() {
  sub="${1:-help}"
  [ $# -gt 0 ] && shift
  case "$sub" in
    on|start)
      if [ -n "${1:-}" ]; then
        case "$1" in *[!0-9]*) _die "port must be numeric" ;; esac
        _call POST /start "{\"port\": $1}" status
      else
        _call POST /start '{}' status
      fi ;;
    off|stop) _call POST /stop '{}' ;;
    status) _call GET /status '' status ;;
    intercept)
      case "${1:-toggle}" in
        on|true|1) _call POST /intercept '{"mode": "on"}' ;;
        off|false|0) _call POST /intercept '{"mode": "off"}' ;;
        toggle) _call POST /intercept '{"mode": "toggle"}' ;;
        *) _die "usage: opc intercept on|off|toggle" ;;
      esac ;;
    filter)
      [ $# -ge 1 ] || _die 'usage: opc filter "<regex>"   (opc filter "" clears)'
      _call POST /filter "{\"regex\": \"$(_json_str "$1")\"}" ;;
    watch) cmd_watch "${1:-0}" ;;
    fmt) cmd_fmt ;;
    listen) cmd_listen "$@" ;;
    last)
      f="$OPC_DIR/last_sent.json"
      [ -f "$f" ] || _die "no $f yet"
      if _have jq; then jq . "$f"; else cat "$f"; fi ;;
    help|-h|--help) cmd_help ;;
    *) cmd_help; exit 2 ;;
  esac
}

main "$@"
